#Requires -RunAsAdministrator
param([Parameter(Mandatory)][string]$Context)
$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
function Need([bool]$v,[string]$m){if(!$v){throw $m}}
function Hash([string]$p){(Get-FileHash -LiteralPath $p -Algorithm SHA256).Hash.ToLowerInvariant()}
$p=Get-Content -LiteralPath $Context -Raw|ConvertFrom-Json
if($p.RootAuthorizedReadOnlyOriginalPublic21BaselineDiagnostic -isnot [bool] -or !$p.RootAuthorizedReadOnlyOriginalPublic21BaselineDiagnostic){Write-Output 'FALSE_AUTHORITY_NO_TASK_OR_PRODUCT_ACTION';return}
Need ($env:GITHUB_ACTIONS-ceq 'true'-and $env:RUNNER_ENVIRONMENT-ceq 'github-hosted'-and $env:GITHUB_REPOSITORY-ceq 'embire2/openwebpbx'-and $env:GITHUB_RUN_ID-ceq $p.runId) 'Only actual disposable CI context'
Need ($p.originalPublic21Source-ceq 'cab93b390ba2e8f33c184f2f085740c2862031a6'-and $p.originalPublic21ArchiveSHA256-ceq 'ce811ae1eaeb17b46f81bdfc0f12b0baa13409bded8f4df6788f8772d0ea855d') 'Exact original public21 source/archive identity required'
Need ($p.originalFailureStage-ceq 'worker_result'-and $p.originalLastTaskResult-eq 1-and $p.originalFreshRun-is[bool]-and $p.originalFreshRun) 'Original actual worker-result failure required; no speculative invocation'
Need ((Hash $PSCommandPath)-ceq $p.operatorSHA256-and (Hash (Join-Path $PSScriptRoot 'readonly-preamble.py'))-ceq $p.collectorSHA256-and (Hash (Join-Path $PSScriptRoot 'Run-ReadOnlyPython.ps1'))-ceq $p.runnerSHA256) 'Exact reviewed diagnostic sources required'
Need ([DateTimeOffset]::UtcNow-lt[DateTimeOffset]::Parse($p.expiresAt)) 'Fresh authority required'
$id=[Guid]::Parse($p.operationUUID).ToString('N');$name='OpenWebPBX-QA-BackupBaselineReadOnly-'+$id;$private=[IO.Path]::GetFullPath($p.privateEvidenceRoot);$expected=Join-Path $env:RUNNER_TEMP ('OpenWebPBXBackupBaselineReadOnly-'+$id);Need ($private-ceq[IO.Path]::GetFullPath($expected)-and !(Test-Path -LiteralPath $private)-and !(Get-ScheduledTask -TaskName $name -ErrorAction SilentlyContinue)) 'Exclusive owned diagnostic namespace required'
$manifestPath=Join-Path $p.verifiedPublic21PackageRoot 'release-manifest.json';Need ((Hash $manifestPath)-ceq $p.public21ManifestSHA256) 'Verified original public21 manifest differs';$manifest=Get-Content $manifestPath -Raw|ConvertFrom-Json
Need ($manifest.version-ceq '1.0.21'-and $manifest.files.'backups.py'-ceq 'a1b032a6ead38af079acb945869845a8f56015823e891dedc2bb22e33e23545e') 'Exact immutable21 package helper required'
foreach($binding in @(@('backup-runtime/python.exe','C:/OpenWebPBX/backup-runtime/python.exe'),@('backup-runtime/python313.zip','C:/OpenWebPBX/backup-runtime/python313.zip'),@('backups.py','C:/OpenWebPBX/tools/backups.py'))){Need ((Hash $binding[1])-ceq $manifest.files.($binding[0])-and (Hash (Join-Path $p.verifiedPublic21PackageRoot $binding[0]))-ceq $manifest.files.($binding[0])) 'Prelaunch original Python/stdlib/helper binding differs'}
$installation=Get-Content 'C:/ProgramData/OpenWebPBX/installation.json' -Raw|ConvertFrom-Json;Need ($installation.Completed-eq $true-and $installation.Version-ceq '1.0.21') 'Original public21 installation required'
$normal=Get-ScheduledTask -TaskName OpenWebPBX-Backups -TaskPath '\';$scheduler=New-Object -ComObject Schedule.Service;$scheduler.Connect();$backup=$scheduler.GetFolder('\').GetTask('OpenWebPBX-Backups');$normalXML=$backup.Xml;$normalSecurity=$backup.GetSecurityDescriptor(7);$normalEnabled=[bool]$normal.Settings.Enabled
Need ($normal.Principal.UserId-in @('SYSTEM','S-1-5-18','NT AUTHORITY\SYSTEM')-and $normal.Actions.Count-eq 1-and $normal.Actions[0].Execute-ceq 'C:\OpenWebPBX\backup-runtime\python.exe'-and $normal.Actions[0].Arguments-ceq '-I "C:\OpenWebPBX\tools\backups.py" worker') 'Exact original normal task identity required'
New-Item -ItemType Directory -Path $private|Out-Null;$acl=[Security.AccessControl.DirectorySecurity]::new();$acl.SetAccessRuleProtection($true,$false);$acl.SetOwner([Security.Principal.SecurityIdentifier]'S-1-5-32-544');foreach($sid in 'S-1-5-18','S-1-5-32-544'){$acl.AddAccessRule([Security.AccessControl.FileSystemAccessRule]::new([Security.Principal.SecurityIdentifier]$sid,'FullControl','ContainerInherit,ObjectInherit','None','Allow'))};Set-Acl -LiteralPath $private -AclObject $acl
Copy-Item (Join-Path $PSScriptRoot 'readonly-preamble.py') (Join-Path $private 'readonly-preamble.py');Copy-Item (Join-Path $PSScriptRoot 'Run-ReadOnlyPython.ps1') (Join-Path $private 'Run-ReadOnlyPython.ps1');Copy-Item $Context (Join-Path $private 'context.private.json');Need ((Hash (Join-Path $private 'readonly-preamble.py'))-ceq $p.collectorSHA256) 'Private staged source differs'
[IO.File]::WriteAllText((Join-Path $private 'normal-backup-task.before.xml'),$normalXML);[IO.File]::WriteAllText((Join-Path $private 'normal-backup-task.before.security.private.txt'),$normalSecurity);[IO.File]::WriteAllText((Join-Path $private 'normal-backup-task.before.enabled.safe.json'),(@{enabled=$normalEnabled}|ConvertTo-Json))
$started=[DateTimeOffset]::UtcNow;[IO.File]::WriteAllText((Join-Path $private 'one-use-intent.safe.json'),(@{original90sDeadline=$started.AddSeconds(90).ToString('o');readOnlyDiagnosticOnly=$true;noWorkerOrProductTaskLifecycle=$true}|ConvertTo-Json),[Text.UTF8Encoding]::new($false))
$definition=$scheduler.NewTask(0);$definition.Principal.UserId='SYSTEM';$definition.Principal.LogonType=5;$definition.Principal.RunLevel=1;$definition.Settings.Enabled=$true;$definition.Settings.MultipleInstances=2;$definition.Settings.ExecutionTimeLimit='PT0S';$action=$definition.Actions.Create(0);$action.Path=Join-Path $env:SystemRoot 'System32\WindowsPowerShell\v1.0\powershell.exe';$action.Arguments='-NoProfile -NonInteractive -ExecutionPolicy Bypass -File "'+(Join-Path $private 'Run-ReadOnlyPython.ps1')+'" -Context "'+(Join-Path $private 'context.private.json')+'"';$action.WorkingDirectory=$private
$null=$scheduler.GetFolder('\').RegisterTaskDefinition($name,$definition,2,'SYSTEM',$null,5,'O:SYG:SYD:P(A;;FA;;;SY)(A;;FA;;;BA)');$owned=$scheduler.GetFolder('\').GetTask($name);Need ($owned.Definition.Principal.UserId-in @('SYSTEM','S-1-5-18')-and $owned.Definition.Principal.LogonType-eq 5-and $owned.Definition.Principal.RunLevel-eq 1) 'Actual owned SYSTEM principal differs';$xml=$owned.Xml;$security=$owned.GetSecurityDescriptor(7);[IO.File]::WriteAllText((Join-Path $private 'owned-task.xml'),$xml);[IO.File]::WriteAllText((Join-Path $private 'owned-task.security.private.txt'),$security)
$null=$owned.Run($null)
do{$present=Test-Path (Join-Path $private 'diagnostic-child-result.safe.json');$current=Get-ScheduledTask -TaskName $name -TaskPath '\';Need ([DateTimeOffset]::UtcNow-lt$started.AddSeconds(90)) 'Original diagnostic90s expired after task query; retain owned task/process/evidence without cleanup';if($present-and [string]$current.State-notin @('Running','Queued')){break};if([DateTimeOffset]::UtcNow-ge$started.AddSeconds(90)){throw 'Original diagnostic90s expired; keep owned task/process/evidence for inspection, no kill or replay'};Start-Sleep -Milliseconds 200}while($true)
$childResult=Get-Content (Join-Path $private 'diagnostic-child-result.safe.json') -Raw|ConvertFrom-Json;Need ($childResult.observationChildFinished -eq $true) 'Diagnostic child ambiguous; retain owned task/evidence without cleanup';$again=$scheduler.GetFolder('\').GetTask($name);Need ($again.Xml-ceq $xml-and $again.GetSecurityDescriptor(7)-ceq $security) 'Owned diagnostic task changed; do not remove foreign definition';$normalAfter=$scheduler.GetFolder('\').GetTask('OpenWebPBX-Backups');Need ($normalAfter.Xml-ceq $normalXML-and $normalAfter.GetSecurityDescriptor(7)-ceq $normalSecurity-and [bool](Get-ScheduledTask -TaskName OpenWebPBX-Backups).Settings.Enabled-eq $normalEnabled) 'Normal backup task definition/security/choice changed'
Need ([DateTimeOffset]::UtcNow-lt$started.AddSeconds(90)) 'Original diagnostic90s expired before cleanup; retain owned task/evidence'
Unregister-ScheduledTask -TaskName $name -TaskPath '\' -Confirm:$false
Write-Output 'READONLY_OBSERVATION_TERMINAL_NO_PRODUCTION_PASS_CLAIM'
